#!/usr/bin/env bash
# apply-mate-update.sh — updates a local Mate folder to the latest version (Gemini fixes included).
#
# Usage (from anywhere):   bash apply-mate-update.sh /path/to/mate
#    or, inside the folder: bash apply-mate-update.sh
#
# What it does:
#   1. Checks the folder looks like the Mate project.
#   2. Backs up every file it will overwrite or delete to .mate-backup-<timestamp>/.
#   3. Writes the updated files and removes docker-compose.host-ollama.yml (the reverted change).
# Your .env file is never touched.
set -euo pipefail

TARGET="${1:-.}"
cd "$TARGET"
if [[ ! -f docker-compose.yml || ! -d backend/app || ! -d frontend/src ]]; then
  echo "This does not look like the Mate project folder: $(pwd)" >&2
  echo "Run: bash apply-mate-update.sh /path/to/mate" >&2
  exit 1
fi

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP=".mate-backup-$STAMP"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# Extract the embedded payload (everything after the __PAYLOAD__ marker).
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 --decode > "$WORK/payload.tgz"
mkdir -p "$WORK/files"
tar -xzf "$WORK/payload.tgz" -C "$WORK/files"

mkdir -p "$BACKUP"
updated=0; added=0
while IFS= read -r -d '' src; do
  rel="${src#"$WORK/files/"}"
  if [[ -f "$rel" ]]; then
    if cmp -s "$src" "$rel"; then continue; fi
    mkdir -p "$BACKUP/$(dirname "$rel")"; cp -p "$rel" "$BACKUP/$rel"; updated=$((updated+1))
  else
    added=$((added+1))
  fi
  mkdir -p "$(dirname "$rel")"
  cp "$src" "$rel"
done < <(find "$WORK/files" -type f -print0)

removed=0
for rel in docker-compose.host-ollama.yml ; do
  if [[ -f "$rel" ]]; then
    mkdir -p "$BACKUP/$(dirname "$rel")"; mv "$rel" "$BACKUP/$rel"; removed=$((removed+1))
  fi
done

if [[ -z "$(ls -A "$BACKUP")" ]]; then rmdir "$BACKUP"; BACKUP="(nothing overwritten)"; fi

echo "Mate updated: $updated files changed, $added added, $removed removed."
echo "Backup of replaced files: $BACKUP"
if [[ -d .git ]]; then echo "This is a git repo: review with 'git status' and commit when ready."; fi
cat <<'NEXT'

Next: rebuild so Docker runs the new code:
  docker compose up -d --build
Then retry in the app (click "Analyse my profile" on your venture).
If the model is not set up yet: bash scripts/connect-gemini.sh
NEXT
exit 0
